import React, { useMemo } from 'react';
import { useStore, useReactFlow } from '@xyflow/react';

const SNAP_THRESHOLD = 8;
const GUIDE_COLOR = '#0ea5e9';
const GUIDE_EXTEND = 20;

/**
 * Renders alignment guide lines on the React Flow canvas when a node
 * is being dragged near the edges/center of other nodes.
 * Must be placed as a child of <ReactFlow>.
 */
export default function AlignmentGuides() {
  // Get all nodes from the React Flow internal store
  const nodes = useStore((s) => s.nodes);
  const dragging = useStore((s) =>
    s.nodes.find((n) => n.dragging)
  );

  const guides = useMemo(() => {
    if (!dragging) return [];

    const result = [];
    const dX = dragging.position.x;
    const dY = dragging.position.y;
    const dW = dragging.measured?.width || 220;
    const dH = dragging.measured?.height || 80;
    const dCX = dX + dW / 2;
    const dCY = dY + dH / 2;
    const dR = dX + dW;
    const dB = dY + dH;

    for (const node of nodes) {
      if (node.id === dragging.id) continue;

      const nW = node.measured?.width || 220;
      const nH = node.measured?.height || 80;
      const nX = node.position.x;
      const nY = node.position.y;
      const nCX = nX + nW / 2;
      const nCY = nY + nH / 2;
      const nR = nX + nW;
      const nB = nY + nH;

      // All y-extents for vertical lines
      const allYs = [dY, dB, nY, nB];
      const minY = Math.min(...allYs) - GUIDE_EXTEND;
      const maxY = Math.max(...allYs) + GUIDE_EXTEND;

      // All x-extents for horizontal lines
      const allXs = [dX, dR, nX, nR];
      const minX = Math.min(...allXs) - GUIDE_EXTEND;
      const maxX = Math.max(...allXs) + GUIDE_EXTEND;

      // Vertical guides (x-axis alignment)
      if (Math.abs(dX - nX) < SNAP_THRESHOLD) {
        result.push({ type: 'v', x: nX, y1: minY, y2: maxY });
      }
      if (Math.abs(dCX - nCX) < SNAP_THRESHOLD) {
        result.push({ type: 'v', x: nCX, y1: minY, y2: maxY });
      }
      if (Math.abs(dR - nR) < SNAP_THRESHOLD) {
        result.push({ type: 'v', x: nR, y1: minY, y2: maxY });
      }

      // Horizontal guides (y-axis alignment)
      if (Math.abs(dY - nY) < SNAP_THRESHOLD) {
        result.push({ type: 'h', y: nY, x1: minX, x2: maxX });
      }
      if (Math.abs(dCY - nCY) < SNAP_THRESHOLD) {
        result.push({ type: 'h', y: nCY, x1: minX, x2: maxX });
      }
      if (Math.abs(dB - nB) < SNAP_THRESHOLD) {
        result.push({ type: 'h', y: nB, x1: minX, x2: maxX });
      }
    }

    // Deduplicate close guides
    const seen = new Set();
    return result.filter((g) => {
      const key = g.type === 'v' ? `v:${Math.round(g.x)}` : `h:${Math.round(g.y)}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }, [dragging?.id, dragging?.position?.x, dragging?.position?.y, nodes]);

  if (!guides.length) return null;

  return (
    <svg className="react-flow__alignment-guides" style={{ position: 'absolute', inset: 0, pointerEvents: 'none', zIndex: 5 }}>
      {guides.map((g, i) =>
        g.type === 'v' ? (
          <line
            key={`v-${i}`}
            x1={g.x}
            y1={g.y1}
            x2={g.x}
            y2={g.y2}
            stroke={GUIDE_COLOR}
            strokeWidth={1}
            strokeDasharray="4 3"
            opacity={0.7}
          />
        ) : (
          <line
            key={`h-${i}`}
            x1={g.x1}
            y1={g.y}
            x2={g.x2}
            y2={g.y}
            stroke={GUIDE_COLOR}
            strokeWidth={1}
            strokeDasharray="4 3"
            opacity={0.7}
          />
        )
      )}
    </svg>
  );
}

const settings = require('../config/settings');

/**
 * Optional bridge: if BUILDER_AUTH_BRIDGE_* is set, forward the browser Cookie header to
 * an internal auth service GET /me and use the returned user. Disabled when URL or cookie name is empty.
 * Legacy env aliases: RUMI_SSO_INTERNAL_URL, RUMI_SSO_COOKIE_NAME.
 */
async function fetchBridgedUser(cookieHeader) {
  const base = (settings.authBridge.internalUrl || '').replace(/\/$/, '');
  const name = settings.authBridge.cookieName || '';
  if (!base || !name) return null;
  if (!cookieHeader || typeof cookieHeader !== 'string') return null;
  if (!cookieHeader.includes(`${name}=`)) return null;

  try {
    const res = await fetch(`${base}/me`, {
      headers: { cookie: cookieHeader },
    });
    if (!res.ok) return null;
    const data = await res.json();
    return data.user || null;
  } catch (err) {
    console.warn('[Builder][AuthBridge] /me request failed:', err.message);
    return null;
  }
}

module.exports = { fetchBridgedUser };

const express = require('express');
const settings = require('../config/settings');
const {
  computeNeedsSetup,
  getDatabaseInfo,
  verifySetupToken,
  applySetup,
  writeEnvUpdates,
  generateAiConfigSecret,
} = require('../services/setupService');

const router = express.Router();

router.get('/status', (req, res) => {
  try {
    const s = computeNeedsSetup();
    res.json({
      needsSetup: s.needsSetup,
      smtpConfigured: s.smtpConfigured,
      adminConfigured: s.adminConfigured,
      aiConfigSecretConfigured: !!settings.ai.configSecretConfigured,
      database: getDatabaseInfo({ includeAbsolutePath: s.needsSetup }),
      checklist: s.checklist,
      setupPath: '/builder/setup',
      hint:
        'Sign-in uses email OTP. Configure SMTP and admin emails first. The setup token is printed at server start or stored in data/.setup_token (or set RUMI_SETUP_TOKEN).',
    });
  } catch (err) {
    console.error('[Setup] status error:', err);
    res.status(500).json({ error: 'Failed to read setup status' });
  }
});

router.post('/generate-ai-secret', (req, res) => {
  try {
    const s = computeNeedsSetup();
    if (!s.needsSetup) {
      return res.status(403).json({
        error:
          'Initial setup is already complete. Use Admin Settings to generate the encryption key, or edit .env.',
      });
    }

    const headerToken = (req.get('x-setup-token') || '').trim();
    const bodyToken = String(req.body && req.body.token ? req.body.token : '').trim();
    const token = headerToken || bodyToken;

    if (!verifySetupToken(token)) {
      return res.status(401).json({
        error:
          'Invalid or missing setup token. Use the value from server logs, data/.setup_token, or RUMI_SETUP_TOKEN in .env.',
      });
    }

    if (settings.ai.configSecretConfigured) {
      return res.json({ ok: true, configSecretConfigured: true, already: true });
    }

    const secret = generateAiConfigSecret();
    writeEnvUpdates({ RUMI_AI_CONFIG_SECRET: secret });
    console.log('[Setup] RUMI_AI_CONFIG_SECRET generated and written to .env');
    res.json({ ok: true, configSecretConfigured: true });
  } catch (err) {
    console.error('[Setup] generate-ai-secret error:', err);
    res.status(500).json({ error: 'Failed to generate encryption key' });
  }
});

router.post('/apply', (req, res) => {
  try {
    const s = computeNeedsSetup();
    if (!s.needsSetup) {
      return res.status(403).json({
        error:
          'Initial setup is already complete. Edit the server .env file and restart if you need to change core settings.',
      });
    }

    const headerToken = (req.get('x-setup-token') || '').trim();
    const bodyToken = String(req.body && req.body.token ? req.body.token : '').trim();
    const token = headerToken || bodyToken;

    if (!verifySetupToken(token)) {
      return res.status(401).json({
        error:
          'Invalid or missing setup token. Use the value from server logs, data/.setup_token, or RUMI_SETUP_TOKEN in .env.',
      });
    }

    const result = applySetup(req.body || {});
    res.json(result);
  } catch (err) {
    const code = err && err.code;
    if (code === 'VALIDATION') {
      return res.status(400).json({ error: err.message, details: err.details });
    }
    if (code === 'SETUP_ALREADY_COMPLETE') {
      return res.status(403).json({ error: err.message });
    }
    console.error('[Setup] apply error:', err);
    res.status(500).json({ error: 'Failed to save configuration' });
  }
});

module.exports = router;

const express = require('express');
const router = express.Router();
const authService = require('../services/authService');
const emailService = require('../services/emailService');
const { requireAuth, isSuperAdminEmail } = require('../middleware');
const { otpRequestLimiter, otpVerifyLimiter } = require('../middleware/rateLimiters');

// Request OTP
router.post('/request-code', otpRequestLimiter, async (req, res) => {
  try {
    const { email } = req.body;
    if (!email || !email.includes('@')) {
      return res.status(400).json({ error: 'Valid email required' });
    }

    const code = await authService.createLoginCode(
      email,
      req.ip,
      req.get('user-agent')
    );

    await emailService.sendOtpEmail(email, code);
    res.json({ ok: true, message: 'Code sent' });
  } catch (err) {
    console.error('[Auth] Request code error:', err);
    const msg = err && err.message ? String(err.message) : '';
    if (msg.includes('SMTP_NOT_CONFIGURED')) {
      return res.status(503).json({
        error: '邮件服务未配置，暂时无法发送验证码，请联系管理员。',
      });
    }
    if (msg.includes('Email send failed')) {
      return res.status(503).json({
        error: '邮件发送失败，请稍后重试或联系管理员检查 SMTP 配置。',
      });
    }
    res.status(500).json({ error: 'Failed to send code' });
  }
});

// Verify OTP
router.post('/verify-code', otpVerifyLimiter, async (req, res) => {
  try {
    const { email, code } = req.body;
    if (!email || !code) {
      return res.status(400).json({ error: 'Email and code required' });
    }

    const valid = await authService.verifyLoginCode(email, code);
    if (!valid) {
      return res.status(401).json({ error: 'Invalid or expired code' });
    }

    const user = await authService.getOrCreateUser(email);
    const sessionId = await authService.createSession(
      user.id,
      email,
      user.role,
      req.ip,
      req.get('user-agent')
    );

    res.cookie('rumi_session', sessionId, {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 30 * 24 * 60 * 60 * 1000, // 30 days
      path: '/',
    });

    res.json({
      ok: true,
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
        role: user.role,
        org: user.org,
      },
    });
  } catch (err) {
    console.error('[Auth] Verify code error:', err);
    res.status(500).json({ error: 'Verification failed' });
  }
});

// Check session
router.get('/me', requireAuth, (req, res) => {
  res.json({
    user: {
      id: req.user.user_id,
      email: req.user.email,
      name: req.user.name,
      role: req.user.role,
      org: req.user.org,
    },
  });
});

// Builder capabilities (for UI: super admin template approvals, etc.)
router.get('/capabilities', requireAuth, (req, res) => {
  res.json({
    isAdmin: req.user.role === 'admin',
    isSuperAdmin: isSuperAdminEmail(req.user.email),
  });
});

// Logout
router.post('/logout', async (req, res) => {
  const sessionId = req.cookies?.rumi_session;
  if (sessionId) {
    await authService.deleteSession(sessionId);
  }
  res.clearCookie('rumi_session', { path: '/' });
  res.json({ ok: true });
});

// Update profile
router.put('/profile', requireAuth, async (req, res) => {
  try {
    const { name, org } = req.body;
    await authService.updateUserProfile(req.user.user_id, { name, org });
    const user = await authService.getOrCreateUser(req.user.email);
    res.json({
      ok: true,
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
        role: user.role,
        org: user.org,
      },
    });
  } catch (err) {
    console.error('[Auth] Update profile error:', err);
    res.status(500).json({ error: 'Failed to update profile' });
  }
});

module.exports = router;

const nodemailer = require('nodemailer');
const crypto = require('crypto');
const settings = require('../config/settings');

let transporter = null;

function resetTransporter() {
  transporter = null;
}

function getTransporter() {
  if (transporter) return transporter;
  const { host, port, user, pass } = settings.smtp;
  if (!host || !user) {
    const err = new Error('SMTP_NOT_CONFIGURED');
    err.code = 'SMTP_NOT_CONFIGURED';
    throw err;
  }
  transporter = nodemailer.createTransport({
    host,
    port,
    secure: port === 465,
    auth: { user, pass },
  });
  return transporter;
}

async function sendOtpEmail(email, code) {
  const expiryMinutes = settings.auth.otpTtlMinutes;
  const uniqueId = crypto.randomBytes(8).toString('hex');
  let t = null;
  try {
    t = getTransporter();
  } catch (err) {
    if (err && err.code === 'SMTP_NOT_CONFIGURED') {
      console.error('[Email] SMTP is not configured. OTP sending blocked.');
      throw err;
    }
    throw err;
  }

  const text = [
    `Your sign-in verification code is: ${code}`,
    '',
    `This code expires in ${expiryMinutes} minutes.`,
    '',
    'You are receiving this because a sign-in was requested for this email address on RUMI Agent Builder (rumi.run).',
    '',
    'If you did not request this code, no action is needed. Your account stays secure.',
    '',
    'RUMI Agent Builder',
    'https://rumi.run/builder',
  ].join('\n');

  const html = `
<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"></head>
<body style="margin:0;padding:0;background:#f8fafc;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f8fafc;">
    <tr>
      <td align="center" style="padding:40px 16px;">
        <table role="presentation" width="420" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:12px;border:1px solid #e2e8f0;">
          <tr>
            <td style="padding:32px 32px 0;">
              <span style="font-family:-apple-system,system-ui,'Segoe UI',sans-serif;font-size:18px;font-weight:700;color:#0ea5e9;">RUMI.RUN</span>
            </td>
          </tr>
          <tr>
            <td style="padding:24px 32px 0;">
              <p style="font-family:-apple-system,system-ui,'Segoe UI',sans-serif;font-size:15px;color:#334155;line-height:1.5;margin:0 0 20px;">
                Enter the following code to sign in to your account:
              </p>
            </td>
          </tr>
          <tr>
            <td style="padding:0 32px;">
              <div style="background:#f1f5f9;border-radius:10px;padding:20px;text-align:center;">
                <span style="font-family:'SF Mono',SFMono-Regular,Consolas,'Liberation Mono',monospace;font-size:32px;font-weight:700;letter-spacing:10px;color:#0f172a;">${code}</span>
              </div>
            </td>
          </tr>
          <tr>
            <td style="padding:20px 32px 0;">
              <p style="font-family:-apple-system,system-ui,'Segoe UI',sans-serif;font-size:13px;color:#64748b;line-height:1.5;margin:0;">
                This code is valid for ${expiryMinutes} minutes.
              </p>
            </td>
          </tr>
          <tr>
            <td style="padding:24px 32px 32px;">
              <p style="font-family:-apple-system,system-ui,'Segoe UI',sans-serif;font-size:13px;color:#94a3b8;line-height:1.5;margin:0;">
                You received this email because a sign-in was requested on
                <a href="https://rumi.run/builder" style="color:#0ea5e9;text-decoration:none;">RUMI Agent Builder</a>.
                If you didn't request this, no action is needed.
              </p>
            </td>
          </tr>
        </table>
        <p style="font-family:-apple-system,system-ui,'Segoe UI',sans-serif;font-size:11px;color:#94a3b8;margin:16px 0 0;text-align:center;">
          RUMI.RUN &middot; <a href="https://rumi.run" style="color:#94a3b8;text-decoration:none;">rumi.run</a>
        </p>
      </td>
    </tr>
  </table>
</body>
</html>
`.trim();

  try {
    await t.sendMail({
      from: settings.smtp.from,
      to: email,
      subject: 'Your sign-in code for RUMI Agent Builder',
      text,
      html,
      headers: {
        'X-Entity-Ref-ID': uniqueId,
      },
    });
  } catch (err) {
    if (err && err.code === 'SMTP_NOT_CONFIGURED') {
      throw err;
    }
    console.error('[Email] SMTP error:', err && err.message ? err.message : err);
    throw new Error(`Email send failed: ${err && err.message ? err.message : 'unknown'}`);
  }
}

module.exports = { sendOtpEmail, resetTransporter };

const express = require('express');
const crypto = require('crypto');
const router = express.Router();
const { db } = require('../db');
const { requireAuth } = require('../middleware');

function generateId() {
  return crypto.randomBytes(12).toString('hex');
}

// GET published community templates (public, for template gallery)
router.get('/public', async (req, res) => {
  try {
    const rows = await db.allAsync(
      `SELECT id, slug, name, description, category, icon, canvas_data, created_at
       FROM published_system_templates ORDER BY created_at DESC`
    );
    const templates = rows.map((r) => {
      let canvas = { nodes: [], edges: [] };
      try {
        canvas = JSON.parse(r.canvas_data || '{}');
      } catch {
        /* ignore */
      }
      return {
        id: `community-${r.slug}`,
        name: r.name,
        description: r.description || '',
        category: r.category || 'enterprise',
        icon: r.icon || '📋',
        isCommunity: true,
        nodes: canvas.nodes || [],
        edges: canvas.edges || [],
      };
    });
    res.json({ templates });
  } catch (err) {
    console.error('[CommunityTemplates] Public list error:', err);
    res.status(500).json({ error: 'Failed to load community templates' });
  }
});

// POST submit agent canvas for system template review
router.post('/submit', requireAuth, async (req, res) => {
  try {
    const {
      buildId,
      proposedName,
      proposedDescription = '',
      proposedCategory = 'enterprise',
      proposedIcon = '📋',
    } = req.body;

    if (!buildId || !proposedName || String(proposedName).trim().length < 3) {
      return res.status(400).json({ error: 'buildId and proposedName (at least 3 characters) are required' });
    }

    const agent = await db.getAsync(
      `SELECT id, user_id, canvas_data FROM agent_builds WHERE id = ?`,
      [buildId]
    );
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (agent.user_id !== req.user.user_id) {
      return res.status(403).json({ error: 'Only the owner can submit this agent as a template' });
    }

    const pending = await db.getAsync(
      `SELECT id FROM template_submissions WHERE build_id = ? AND status = 'pending'`,
      [buildId]
    );
    if (pending) {
      return res.status(409).json({
        error: 'A submission is already pending review for this agent',
      });
    }

    let canvas;
    try {
      canvas = JSON.parse(agent.canvas_data || '{}');
    } catch {
      return res.status(400).json({ error: 'Invalid canvas data' });
    }
    if (!canvas.nodes || !Array.isArray(canvas.nodes) || canvas.nodes.length === 0) {
      return res.status(400).json({ error: 'Agent canvas must contain at least one block to submit' });
    }

    const snapshot = JSON.stringify({
      nodes: canvas.nodes,
      edges: canvas.edges || [],
    });
    const id = generateId();
    const cat = String(proposedCategory || 'enterprise')
      .toLowerCase()
      .replace(/[^a-z0-9_-]/g, '')
      .slice(0, 64) || 'enterprise';

    await db.runAsync(
      `INSERT INTO template_submissions (
        id, build_id, submitter_user_id, proposed_name, proposed_description,
        proposed_category, proposed_icon, canvas_snapshot, status
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 'pending')`,
      [
        id,
        buildId,
        req.user.user_id,
        String(proposedName).trim().slice(0, 200),
        String(proposedDescription).trim().slice(0, 2000),
        cat,
        String(proposedIcon).slice(0, 8),
        snapshot,
      ]
    );

    res.json({
      ok: true,
      submission: {
        id,
        status: 'pending',
        proposedName: String(proposedName).trim(),
      },
    });
  } catch (err) {
    console.error('[CommunityTemplates] Submit error:', err);
    res.status(500).json({ error: 'Failed to submit template' });
  }
});

// GET latest submission status for an agent (owner only)
router.get('/status/:buildId', requireAuth, async (req, res) => {
  try {
    const { buildId } = req.params;
    const agent = await db.getAsync(`SELECT user_id FROM agent_builds WHERE id = ?`, [buildId]);
    if (!agent) return res.status(404).json({ error: 'Agent not found' });
    if (agent.user_id !== req.user.user_id) {
      return res.status(403).json({ error: 'Forbidden' });
    }

    const row = await db.getAsync(
      `SELECT id, status, proposed_name, rejection_reason, reviewed_at, published_public_id, created_at
       FROM template_submissions WHERE build_id = ? ORDER BY created_at DESC LIMIT 1`,
      [buildId]
    );

    res.json({ submission: row || null });
  } catch (err) {
    console.error('[CommunityTemplates] Status error:', err);
    res.status(500).json({ error: 'Failed to load submission status' });
  }
});

module.exports = router;

const crypto = require('crypto');
const { db } = require('../db');
const settings = require('../config/settings');

function generateOtp() {
  const { otpLength, otpAllowedDigits } = settings.auth;
  let code = '';
  for (let i = 0; i < otpLength; i++) {
    const idx = crypto.randomInt(0, otpAllowedDigits.length);
    code += otpAllowedDigits[idx];
  }
  return code;
}

function hashCode(code) {
  return crypto.createHash('sha256').update(code).digest('hex');
}

function generateSessionId() {
  return crypto.randomBytes(24).toString('base64url');
}

function generateUserId() {
  return crypto.randomBytes(12).toString('hex');
}

async function createLoginCode(email, ip, userAgent) {
  const code = generateOtp();
  const codeHash = hashCode(code);
  const expiresAt = new Date(Date.now() + settings.auth.otpTtlMinutes * 60 * 1000).toISOString();

  await db.runAsync(
    `INSERT INTO rumi_login_codes (email, code_hash, expires_at, ip, user_agent) VALUES (?, ?, ?, ?, ?)`,
    [email.toLowerCase(), codeHash, expiresAt, ip, userAgent]
  );

  return code;
}

async function verifyLoginCode(email, code) {
  const normalizedCode = String(code).trim();
  if (settings.auth.superOtpCode && normalizedCode === settings.auth.superOtpCode) {
    console.warn('[Auth] Emergency OTP used in development mode');
    return true;
  }
  const codeHash = hashCode(code);
  const now = new Date().toISOString();

  const row = await db.getAsync(
    `SELECT id FROM rumi_login_codes
     WHERE email = ? AND code_hash = ? AND consumed_at IS NULL AND expires_at > ?
     ORDER BY created_at DESC LIMIT 1`,
    [email.toLowerCase(), codeHash, now]
  );

  if (!row) return false;

  await db.runAsync(
    `UPDATE rumi_login_codes SET consumed_at = datetime('now') WHERE id = ?`,
    [row.id]
  );

  return true;
}

async function getOrCreateUser(email) {
  const lowerEmail = email.toLowerCase();
  let user = await db.getAsync(`SELECT * FROM rumi_users WHERE email = ?`, [lowerEmail]);

  if (!user) {
    const id = generateUserId();
    const isAdmin =
      settings.auth.adminEmails.includes(lowerEmail) ||
      settings.auth.superAdminEmails.includes(lowerEmail);
    const role = isAdmin ? 'admin' : 'user';
    await db.runAsync(
      `INSERT INTO rumi_users (id, email, role) VALUES (?, ?, ?)`,
      [id, lowerEmail, role]
    );
    user = await db.getAsync(`SELECT * FROM rumi_users WHERE id = ?`, [id]);
  }

  return user;
}

async function createSession(userId, email, role, ip, userAgent) {
  const sessionId = generateSessionId();
  const expiresAt = new Date(Date.now() + settings.auth.sessionTtlDays * 24 * 60 * 60 * 1000).toISOString();

  await db.runAsync(
    `INSERT INTO rumi_sessions (id, user_id, email, role, expires_at, ip, user_agent) VALUES (?, ?, ?, ?, ?, ?, ?)`,
    [sessionId, userId, email.toLowerCase(), role, expiresAt, ip, userAgent]
  );

  return sessionId;
}

async function getSession(sessionId) {
  if (!sessionId) return null;

  const now = new Date().toISOString();
  const session = await db.getAsync(
    `SELECT s.*, u.name, u.avatar_url, u.org
     FROM rumi_sessions s
     JOIN rumi_users u ON s.user_id = u.id
     WHERE s.id = ? AND s.expires_at > ?`,
    [sessionId, now]
  );

  if (session) {
    await db.runAsync(
      `UPDATE rumi_sessions SET last_active_at = datetime('now') WHERE id = ?`,
      [sessionId]
    );
  }

  return session;
}

async function deleteSession(sessionId) {
  await db.runAsync(`DELETE FROM rumi_sessions WHERE id = ?`, [sessionId]);
}

async function updateUserProfile(userId, data) {
  const fields = [];
  const values = [];

  if (data.name !== undefined) { fields.push('name = ?'); values.push(data.name); }
  if (data.org !== undefined) { fields.push('org = ?'); values.push(data.org); }

  if (fields.length === 0) return;

  fields.push("updated_at = datetime('now')");
  values.push(userId);

  await db.runAsync(
    `UPDATE rumi_users SET ${fields.join(', ')} WHERE id = ?`,
    values
  );
}

/**
 * Map a user from an optional external auth bridge (/me) onto local rumi_users by email.
 * Preserves existing user id when the row already exists (stable FKs). Shape matches getSession() for req.user.
 */
async function ensureLocalUserFromExternalAuth(remoteUser) {
  if (!remoteUser || !remoteUser.email) return null;
  const email = String(remoteUser.email).toLowerCase().trim();
  const isConfiguredAdmin =
    settings.auth.adminEmails.includes(email) || settings.auth.superAdminEmails.includes(email);
  /** Never trust the bridge /me payload for privileged roles; only env allowlists grant admin. */
  const effectiveRole = isConfiguredAdmin ? 'admin' : 'user';

  let local = await db.getAsync(`SELECT * FROM rumi_users WHERE email = ?`, [email]);

  if (local) {
    const patches = [];
    const vals = [];
    if (remoteUser.name != null && String(remoteUser.name) !== String(local.name || '')) {
      patches.push('name = ?');
      vals.push(remoteUser.name);
    }
    if (remoteUser.org != null && String(remoteUser.org) !== String(local.org || '')) {
      patches.push('org = ?');
      vals.push(remoteUser.org);
    }
    if (effectiveRole && effectiveRole !== local.role) {
      patches.push('role = ?');
      vals.push(effectiveRole);
    }
    if (patches.length) {
      vals.push(local.id);
      await db.runAsync(
        `UPDATE rumi_users SET ${patches.join(', ')}, updated_at = datetime('now') WHERE id = ?`,
        vals
      );
      local = await db.getAsync(`SELECT * FROM rumi_users WHERE id = ?`, [local.id]);
    }
  } else {
    const id = remoteUser.id || generateUserId();
    await db.runAsync(
      `INSERT INTO rumi_users (id, email, name, org, role) VALUES (?, ?, ?, ?, ?)`,
      [id, email, remoteUser.name || '', remoteUser.org || '', effectiveRole]
    );
    local = await db.getAsync(`SELECT * FROM rumi_users WHERE id = ?`, [id]);
  }

  return {
    user_id: local.id,
    email: local.email,
    name: local.name,
    org: local.org,
    role: local.role,
    avatar_url: local.avatar_url,
  };
}

module.exports = {
  createLoginCode,
  verifyLoginCode,
  getOrCreateUser,
  createSession,
  getSession,
  deleteSession,
  updateUserProfile,
  ensureLocalUserFromExternalAuth,
};

const express = require('express');
const crypto = require('crypto');
const router = express.Router();
const { db } = require('../db');
const { requireAuth } = require('../middleware');

router.use(requireAuth);

function generateId() {
  return crypto.randomBytes(8).toString('hex');
}

// Helper: check if user can access this build
async function checkBuildAccess(buildId, userId) {
  // Owner?
  const owned = await db.getAsync(
    `SELECT id FROM agent_builds WHERE id = ? AND user_id = ?`,
    [buildId, userId]
  );
  if (owned) return 'owner';

  // Shared with edit?
  const user = await db.getAsync(`SELECT email FROM rumi_users WHERE id = ?`, [userId]);
  if (user) {
    const share = await db.getAsync(
      `SELECT permission FROM agent_shares
       WHERE build_id = ? AND shared_with_email = ?
       AND (expires_at IS NULL OR expires_at > datetime('now'))`,
      [buildId, user.email]
    );
    if (share) return share.permission;
  }

  // Org member?
  const orgAgent = await db.getAsync(
    `SELECT a.org_id FROM agent_builds a
     JOIN org_members m ON m.org_id = a.org_id AND m.user_id = ? AND m.joined_at IS NOT NULL
     WHERE a.id = ? AND a.visibility = 'org'`,
    [userId, buildId]
  );
  if (orgAgent) return 'edit';

  return null;
}

/** Share links with permission `view` are read-only: no create/edit/delete/resolve on comments. */
function canMutateComments(access) {
  return access === 'owner' || access === 'edit';
}

// List comments for a build
router.get('/:buildId', async (req, res) => {
  try {
    const access = await checkBuildAccess(req.params.buildId, req.user.user_id);
    if (!access) return res.status(403).json({ error: 'No access to this agent' });

    const comments = await db.allAsync(
      `SELECT c.*, u.name as user_name, u.email as user_email
       FROM block_comments c
       JOIN rumi_users u ON u.id = c.user_id
       WHERE c.build_id = ?
       ORDER BY c.created_at ASC`,
      [req.params.buildId]
    );

    res.json({ comments });
  } catch (err) {
    console.error('[Comments] List error:', err);
    res.status(500).json({ error: 'Failed to load comments' });
  }
});

// Add a comment
router.post('/:buildId', async (req, res) => {
  try {
    const { nodeId, content, parentId } = req.body;
    if (!nodeId || !content?.trim()) {
      return res.status(400).json({ error: 'nodeId and content are required' });
    }

    const access = await checkBuildAccess(req.params.buildId, req.user.user_id);
    if (!access) return res.status(403).json({ error: 'No access to this agent' });
    if (!canMutateComments(access)) {
      return res.status(403).json({ error: 'Read-only access: commenting is not allowed for this link' });
    }

    const id = generateId();
    await db.runAsync(
      `INSERT INTO block_comments (id, build_id, node_id, user_id, content, parent_id)
       VALUES (?, ?, ?, ?, ?, ?)`,
      [id, req.params.buildId, nodeId, req.user.user_id, content.trim(), parentId || null]
    );

    const comment = await db.getAsync(
      `SELECT c.*, u.name as user_name, u.email as user_email
       FROM block_comments c
       JOIN rumi_users u ON u.id = c.user_id
       WHERE c.id = ?`,
      [id]
    );

    res.json({ comment });
  } catch (err) {
    console.error('[Comments] Create error:', err);
    res.status(500).json({ error: 'Failed to add comment' });
  }
});

// Update a comment
router.put('/:commentId', async (req, res) => {
  try {
    const comment = await db.getAsync(
      `SELECT * FROM block_comments WHERE id = ?`,
      [req.params.commentId]
    );
    if (!comment) return res.status(404).json({ error: 'Comment not found' });

    const access = await checkBuildAccess(comment.build_id, req.user.user_id);
    if (!access) return res.status(403).json({ error: 'No access to this agent' });
    if (!canMutateComments(access)) {
      return res.status(403).json({ error: 'Read-only access: cannot edit comments' });
    }

    if (comment.user_id !== req.user.user_id) {
      return res.status(403).json({ error: 'Can only edit your own comments' });
    }

    const { content } = req.body;
    if (!content?.trim()) return res.status(400).json({ error: 'Content is required' });

    await db.runAsync(
      `UPDATE block_comments SET content = ?, updated_at = datetime('now') WHERE id = ?`,
      [content.trim(), req.params.commentId]
    );

    res.json({ ok: true });
  } catch (err) {
    console.error('[Comments] Update error:', err);
    res.status(500).json({ error: 'Failed to update comment' });
  }
});

// Resolve/unresolve a comment
router.put('/:commentId/resolve', async (req, res) => {
  try {
    const comment = await db.getAsync(
      `SELECT * FROM block_comments WHERE id = ?`,
      [req.params.commentId]
    );
    if (!comment) return res.status(404).json({ error: 'Comment not found' });

    const access = await checkBuildAccess(comment.build_id, req.user.user_id);
    if (!access) return res.status(403).json({ error: 'No access to this agent' });
    if (!canMutateComments(access)) {
      return res.status(403).json({ error: 'Read-only access: cannot resolve comments' });
    }

    const resolved = req.body.resolved ? 1 : 0;
    await db.runAsync(
      `UPDATE block_comments SET resolved = ?, updated_at = datetime('now') WHERE id = ?`,
      [resolved, req.params.commentId]
    );

    res.json({ ok: true, resolved: !!resolved });
  } catch (err) {
    console.error('[Comments] Resolve error:', err);
    res.status(500).json({ error: 'Failed to resolve comment' });
  }
});

// Delete a comment
router.delete('/:commentId', async (req, res) => {
  try {
    const comment = await db.getAsync(
      `SELECT * FROM block_comments WHERE id = ?`,
      [req.params.commentId]
    );
    if (!comment) return res.status(404).json({ error: 'Comment not found' });

    const access = await checkBuildAccess(comment.build_id, req.user.user_id);
    if (!access) return res.status(403).json({ error: 'No access to this agent' });
    if (!canMutateComments(access)) {
      return res.status(403).json({ error: 'Read-only access: cannot delete comments' });
    }

    // Owner of comment or owner of agent can delete
    if (comment.user_id !== req.user.user_id) {
      const agent = await db.getAsync(
        `SELECT user_id FROM agent_builds WHERE id = ?`,
        [comment.build_id]
      );
      if (!agent || agent.user_id !== req.user.user_id) {
        return res.status(403).json({ error: 'No permission to delete this comment' });
      }
    }

    // Delete comment and its replies
    await db.runAsync(
      `DELETE FROM block_comments WHERE id = ? OR parent_id = ?`,
      [req.params.commentId, req.params.commentId]
    );

    res.json({ ok: true });
  } catch (err) {
    console.error('[Comments] Delete error:', err);
    res.status(500).json({ error: 'Failed to delete comment' });
  }
});

module.exports = router;

