/** Per-route JSON body limits to reduce abuse; large canvases only on agents (and AI assist). */
module.exports = {
  jsonAuth: express.json({ limit: '48kb' }),
  jsonSmall: express.json({ limit: '256kb' }),
  jsonMedium: express.json({ limit: '1mb' }),
  jsonAi: express.json({ limit: '2mb' }),
  jsonAgents: express.json({ limit: '10mb' }),
};

const rateLimit = require('express-rate-limit');

/** Limit OTP request spam (per IP). */
const otpRequestLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many code requests from this address. Wait and try again.' },
});

/** Limit OTP verification attempts (per IP). */
const otpVerifyLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 60,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many verification attempts. Wait and try again.' },
});

module.exports = { otpRequestLimiter, otpVerifyLimiter };
